1	import { portByCode } from "@harbor/dispatch/ports/registry";
2	
3	function stamp(instant: Date, timeZone: string): string {
4	  const parts = new Intl.DateTimeFormat("en-GB", {
5	    timeZone,
6	    year: "numeric",
7	    month: "2-digit",
8	    day: "2-digit",
9	    hour: "2-digit",
10	    minute: "2-digit",
11	    hourCycle: "h23",
12	  }).formatToParts(instant);
13	  const get = (type: string) => parts.find((p) => p.type === type)?.value ?? "";
14	  return `${get("year")}-${get("month")}-${get("day")} ${get("hour")}:${get("minute")}`;
15	}
16	
17	export function localArrival(eta: Date, locode: string): string {
18	  const port = portByCode(locode);
19	  if (!port) {
20	    throw new RangeError(`unknown port: ${locode}`);
21	  }
22	  return stamp(eta, "UTC");
23	}
